insert into marketing.settings (key, value) values ('content', '{"MORNING":[{"app":"all","hook":"אף אחד לא בוחר קבוצה. היא בוחרת אותך.","body":"זה התחיל ביד של אבא, במדרגות, בריח של גרעינים.\nמאז עברו שנים, החולצות התחלפו — האהבה לא.\nבנינו מקום אחד לכל מה שאוהד מרגיש. בוקר טוב, משפחה.","visual":"צילום ארכיוני מגורען: יד של אב ויד של ילד על מעקה יציע. טקסט קטן בפינה."},{"app":"fanlife","hook":"אותו מועדון. מסעות שונים. עולם אחד.","body":"FAN LIFE הוא הבית של האוהד: 13 שערים של משחקים, ארכיון חי, וסיפור החיים שלך עם הקבוצה.\nאולימפיאקוס, פנאתינאיקוס, AEK, הפועל, סלטיק ועוד — כל אחד עם עולם משלו.","visual":"קולאז׳ מגזין שנות ה-70: 8 סמלים בעיגולים, כותרת גדולה FAN LIFE."},{"app":"theworker","hook":"יש אנשים שזוכרים תאריכים. אנחנו זוכרים שערים.","body":"THE WORKER הוא משחק ההיסטוריה של הפועל תל אביב — 13 שערים כמו בבלומפילד.\nמי פתח בגמר? איזה ספונסר היה על החולצה? בוא תוכיח לעצמך.","visual":"שער בלומפילד במספר 5, הדפס משי אדום-נייבי על נייר קרם."},{"app":"all","hook":"מה הדבר הראשון שאתה בודק בבוקר?","body":"לא מיילים. לא חדשות.\nאת הטבלה. את הסגל. את מה שאמרו אתמול באולפן.\nאם זה אתה — אתה במקום הנכון.","visual":"מסך טלפון ליד כוס קפה, על המסך טבלת ליגה מטושטשת."},{"app":"dubid","hook":"שחקן אחד מכל קבוצה. זה כל הכלל.","body":"DUBID הוא פנטזי של ליגת העל — אבל עם טוויסט שכונתי: מכל קבוצה אתה בוחר רק שחקן אחד.\nקל להבין, קשה לנצח.","visual":"גריד של 14 סמלים מצויירים ביד, בכל אחד צללית של שחקן."},{"app":"all","hook":"הקבוצה שלך הפסידה. אתה עדיין פה.","body":"זה ההבדל בין צופה לאוהד.\nצופה מחליף ערוץ. אוהד מחליף רק גרביים — את המזל.\nבוקר טוב לכל מי שנשאר.","visual":"צילום שחור-לבן של יציע ריק אחרי משחק, צעיף אחד נשאר על כיסא."},{"app":"offsides","hook":"כל משחק הוא 90 דקות של \"אמרתי לך\".","body":"OFFSIDES: זירות ניחושים עם החברים, שאלות פלאש בזמן אמת, וטבלה שמראה מי באמת מבין.\nמשחק סימולציה חינמי — בלי כסף אמיתי, רק כבוד.","visual":"מסך טלפון עם שאלת פלאש \"מי יבקיע ראשון?\" בעיצוב אורות אצטדיון."},{"app":"theworker","hook":"הפועל זה לא קבוצה. זה מעמד.","body":"מאה שנה של אדום. של פועלים, של אוסישקין, של בלומפילד.\nTHE WORKER שומר את הכל — ונותן לך לשחק בזה.","visual":"פטיש ומגל מסמל הפועל ההיסטורי, הדפס משי מבוגר."},{"app":"fanlife","hook":"הסיפור שלך עם הקבוצה ראוי לספר.","body":"ב-FAN LIFE יש LIFE — סימולציה של חיי אוהד: ילדות, ימי משחק, הבטחות, חברים.\nכל בחירה משנה את הסיפור.","visual":"ציור פיקסלי של ילד בחולצה אדומה עומד מול שער אצטדיון."},{"app":"all","hook":"הריח של דשא בשבת בצהריים.","body":"אי אפשר להסביר את זה למי שלא היה שם.\nאז בנינו את זה בשבילך.\nתייג את מי שלקח אותך למשחק הראשון.","visual":"קלוז-אפ דשא עם קו גיר לבן ונעל מסמרים ישנה."},{"app":"dubid","hook":"מי השחקן שהיית לוקח מהקבוצה של האקס שלך?","body":"בדוביד גם מהקבוצה השנואה אתה חייב לבחור אחד.\nזה הרגע שבו אוהד הופך לאסטרטג.","visual":"מם מעוצב: שני כפתורים — \"לבחור את הכוכב שלהם\" / \"לבחור את הספסל\". זיעה."},{"app":"all","hook":"יש לך חולצה שאתה לא מכבס לפני משחק?","body":"כולנו מאמינים קצת.\nספר לנו בתגובות מה הטקס שלך — הכי מטורף מקבל פוסט.","visual":"חולצה מקופלת על כיסא, תאורת בוקר, טקסט \"הטקס שלך?\"."},{"app":"fanlife","hook":"כמה אתה באמת מכיר את המועדון שלך?","body":"טריוויה בארבע רמות — קל, בינוני, קשה, מומחה. כל השאלות מהארכיון האמיתי של הקבוצה.\nבלי ניחושים, רק עובדות.","visual":"כרטיס שאלה בסגנון מגזין, ארבעה כפתורים ב-4 צבעים."},{"app":"offsides","hook":"החבר הכי חכם בקבוצת הווטסאפ? תכף נראה.","body":"פתחו זירה ב-OFFSIDES, שלחו קישור, וכל אחד מנחש לפני השריקה.\nהטבלה לא משקרת.","visual":"צילום מסך של קבוצת וואטסאפ עם קישור לזירה, אימוג׳י 🧨."},{"app":"theworker","hook":"כל שחקן לבש פעם חולצה. אנחנו יודעים איזו.","body":"ב-THE WORKER כל שחקן מקבל את החולצה המקורית מהעונה שבה שיחק.\n168 חולצות מתועדות, מ-1949 עד היום.","visual":"קיר של חולצות אדומות על קולבים, מסודרות לפי עשורים."},{"app":"all","hook":"היית מוותר על חתונה בשביל דרבי?","body":"אל תענה מהר. אנחנו יודעים את התשובה.","visual":"טקסט גדול על רקע אדום: \"חתונה או דרבי?\" עם שתי אפשרויות."},{"app":"fanlife","hook":"יש שערים שזוכרים לנצח.","body":"בשער 8 של FAN LIFE משחזרים שער היסטורי נגיעה-נגיעה: גוררים את השחקנים, מוסרים, בועטים.\nואז רואים את המקור.","visual":"דיאגרמת מגרש מצויירת עם חיצים של מהלך שער."},{"app":"dubid","hook":"הבחירה שלך לשבת כבר מוכנה?","body":"המחזור קרוב. 14 קבוצות, 14 שחקנים, קפטן אחד.\nמי שמחכה לרגע האחרון — מפספס.","visual":"שעון חול מצוייר עם סמלי קבוצות נופלים בתוכו."},{"app":"all","hook":"כדורגל זה לא החיים. זה יותר טוב.","body":"כי בחיים אין 90 דקות שבהן כל העיר נושמת ביחד.\nבוקר של אוהדים. ❤️","visual":"פנורמה של יציע מלא עם עשן צבעוני, גרעין צילום עבה."},{"app":"theworker","hook":"הסבא שלך היה בבלומפילד. ואתה?","body":"שאלות על משחקים ששיחקו לפני שנולדת — וכשתענה נכון, תרגיש שהיית שם.","visual":"כרטיס כניסה ישן לבלומפילד עם קרע, מחיר בלירות."},{"app":"offsides","hook":"אתה מנחש תוצאות כל סופ\"ש בראש. עכשיו זה סופר.","body":"נקודות על תוצאה מדויקת, על מחצית, על מי פותח.\nוסטריק יומי למי שחוזר כל יום.","visual":"לוח תוצאות ישן עם נקודות 🔥 על כל ניחוש."},{"app":"fanlife","hook":"תעשה לעצמך את ההרכב של כל הזמנים.","body":"שער 1 ב-FAN LIFE: 11 שחקנים מכל ההיסטוריה של המועדון. בלי ציונים, בלי שופטים. רק אתה.","visual":"מגרש מלמעלה עם 11 חולצות וינטג׳ במבנה 4-3-3."},{"app":"all","hook":"אתה זוכר איפה ראית את הגול הכי גדול בחיים שלך?","body":"אנחנו כן. הוא נמצא אצלנו בארכיון.\nספר לנו בתגובות — באיזה משחק בכית?","visual":"שולחן סלון שנות ה-90, טלוויזיה ישנה, קבוצת חברים קופצת."},{"app":"dubid","hook":"קצת שכונה, הרבה כדורגל.","body":"DUBID נולד בשכונה: כמו בוויכוח על הספסל — \"מכל קבוצה אחד, ונראה מי מבין\".\nעכשיו זה אפליקציה.","visual":"ספסל ברחוב, שלושה חבר׳ה מתווכחים עם עיתון ספורט."},{"app":"theworker","hook":"השער הכי קשה ב-THE WORKER? שער 11.","body":"זה שער החוץ. שם אין אדום בכלל.\nמי שנכנס — מסתכל על הפוסטר של מישהו אחר.","visual":"שער כחול-נייבי עם מספר 11, בלי אף נגיעה של אדום."},{"app":"fanlife","hook":"כל מועדון מגיע לבית משלו.","body":"ב-FAN LIFE לכל קבוצה יש עולם: צבעים, יציע, שער אהוב, משחקים, וסיפור.\nבחר את שלך.","visual":"שמונה דלתות בצבעי מועדונים שונים, בסגנון קומיקס."},{"app":"all","hook":"ההבדל בין אוהד לאוהד אמיתי? אין כזה.","body":"מי שאוהב — אוהד. לא משנה כמה משחקים, לא משנה כמה כסף.\nכולם מוזמנים.","visual":"קבוצת אנשים מגילאים שונים בצעיפים, מחובקים בגב למצלמה."},{"app":"offsides","hook":"שאלת פלאש: הקורנר הבא — גול או לא?","body":"ב-OFFSIDES השאלות צצות תוך כדי המשחק. 30 שניות לענות.\nזה כמו לראות משחק פעמיים.","visual":"כפתור \"כן/לא\" ענק על רקע מגרש לילה עם ספירה לאחור."},{"app":"fanlife","hook":"פרה עיוורת: מי השחקן?","body":"מקבלים רמז אחרי רמז — עונה, מספר, משחק — וצריך לנחש את השחקן כמה שיותר מהר.\nאפשר גם דו-קרב חי עם חבר.","visual":"צללית שחקן עם סימן שאלה, רמזים כפתקים צהובים-כתומים."},{"app":"all","hook":"תודה שאתה פה.","body":"חודש שלם של כדורגל, זיכרונות ומשחקים מחכה לך בעמוד הזה.\nתפעיל התראות — שלא תפספס.","visual":"פוסטר מגזין: \"תודה\" בכתב יד, חותמת DUBEL TEAM."}],"CAROUSEL":[{"app":"fanlife","hook":"13 שערים. 13 משחקים. מועדון אחד.","body":"שקף 1: 13 שערים — איזה שלך?\nשקף 2: הרכב כל הזמנים\nשקף 3: טריוויה ב-4 רמות\nשקף 4: שחזור שער היסטורי\nשקף 5: ומשחק חולצות — תבנה את החולצה מהעונה הנכונה","visual":"5 שקפים בסגנון מגזין 1972, כל שקף שער ממוספר."},{"app":"dubid","hook":"איך משחקים DUBID ב-30 שניות","body":"שקף 1: בוחרים שחקן אחד מכל קבוצה\nשקף 2: בוחרים קפטן (נקודות כפולות)\nשקף 3: השחקנים מקבלים נקודות על שערים, בישולים ושער נקי\nשקף 4: טבלה מול כל המדינה\nשקף 5: ושולחים את ההרכב לחברים","visual":"קומיקס 5 פריימים עם יד שבוחרת קלפים."},{"app":"offsides","hook":"OFFSIDES: מדריך למנחש המתחיל","body":"שקף 1: פותחים זירה למשחק\nשקף 2: מזמינים חברים בקישור\nשקף 3: מנחשים מחצית, תוצאה ומי פותח\nשקף 4: שאלות פלאש בזמן המשחק\nשקף 5: טבלה, פודיום וסטורי ניצחון. בלי כסף אמיתי.","visual":"שקפים כהים עם אורות אצטדיון כתומים."},{"app":"theworker","hook":"5 דברים שלא ידעת על החולצות של הפועל","body":"שקף 1: לכל עשור — סמל משלו\nשקף 2: הסמל משתנה לפי צבע הבד\nשקף 3: יש חולצות שהספונסר שלהן היה תושב העיר\nשקף 4: 168 חולצות מתועדות\nשקף 5: נסה לבנות אחת בעצמך — שער 4","visual":"כל שקף חולצה אחרת מהארכיון עם חץ על פרט."},{"app":"fanlife","hook":"LIFE: סימולציה של חיים של אוהד","body":"שקף 1: מתחילים כילד\nשקף 2: הליכה ראשונה למגרש\nשקף 3: חברים, משפחה, הבטחות\nשקף 4: כל בחירה משנה את הסיפור\nשקף 5: איזה אוהד תהיה?","visual":"פיקסל-ארט: אותה דמות ב-5 גילאים."},{"app":"all","hook":"חמש אפליקציות. אוהד אחד.","body":"שקף 1: FAN LIFE — הבית\nשקף 2: THE WORKER — העומק של הפועל\nשקף 3: DUBID — הפנטזי של ליגת העל\nשקף 4: OFFSIDES — ניחושים חיים עם חברים\nשקף 5: FUCK YOU — רק בימי דרבי 😉","visual":"חמישה כרטיסים בצבעים שונים, מחוברים בחוט אדום."},{"app":"dubid","hook":"הטעויות שעולות לך מחזור בדוביד","body":"שקף 1: לבחור רק כוכבים\nשקף 2: לשכוח לבדוק פציעות\nשקף 3: קפטן על שחקן שמשחק חוץ\nשקף 4: להשאיר הרכב של שבוע שעבר\nשקף 5: לא לשלוח לחברים (ולא לעקוץ)","visual":"סגנון \"אל תעשו את זה\" עם איקסים אדומים."},{"app":"fanlife","hook":"רויאל ראמבל: ההרכב מול תקציב","body":"שקף 1: 33-35 מיליון יורו לבנות 11\nשקף 2: כל שחקן במחיר אחר\nשקף 3: מסובבים, בוחרים קו, חותמים\nשקף 4: משחקים מול חבר בקישור\nשקף 5: מי בנה טוב יותר?","visual":"מכונת מזל עם קלפי שחקנים וינטג׳."},{"app":"offsides","hook":"3 טיפים לנצח בזירה","body":"שקף 1: תוצאה מדויקת = 5 נקודות\nשקף 2: הבוסט מכפיל שאלה אחת — אבל אתה לא יודע איזו\nשקף 3: שאלות פלאש הן המקום לטפס\nשקף 4: סטריק יומי בונה יתרון\nשקף 5: והכי חשוב — לעקוץ בצ׳אט","visual":"אינפוגרפיקה כתומה-כחולה עם אייקונים."},{"app":"theworker","hook":"ציר הזמן של הפועל — תסדר אותו","body":"שקף 1: אירוע\nשקף 2: אירוע\nשקף 3: אירוע\nשקף 4: איזה קרה קודם?\nשקף 5: שער 13 ב-THE WORKER — ציר הזמן","visual":"ציר זמן אדום עם כרטיסים הפוכים."},{"app":"fanlife","hook":"Legends Manager: תנהל את האגדות","body":"שקף 1: דראפט של אגדות המועדון\nשקף 2: עונה שלמה מול קבוצות אמיתיות\nשקף 3: קפטן, חילופים, טקטיקה\nשקף 4: תקצירי משחק בפיקסלים\nשקף 5: האם תזכה באליפות?","visual":"לוגו Legends Manager מבריק על רקע לילה."},{"app":"all","hook":"איך לשרוד שבוע בלי כדורגל (אי אפשר)","body":"שקף 1: ראשון — טריוויה\nשקף 2: שני — שחזור שער\nשקף 3: שלישי — דראפט אגדות\nשקף 4: רביעי — ארכיון חולצות\nשקף 5: חמישי — ההרכב לשבת. אין פספוס.","visual":"לוח שבועי מצוייר עם פעילות לכל יום."},{"app":"dubid","hook":"הקפטן: ההחלטה שמנצחת מחזורים","body":"שקף 1: הקפטן מקבל נקודות כפולות\nשקף 2: משחק בית > משחק חוץ\nשקף 3: מי בכושר — לא מי מפורסם\nשקף 4: יריבה חלשה = הזדמנות\nשקף 5: ועכשיו — מי הקפטן שלך?","visual":"סרט קפטן על זרוע, קלוז-אפ דרמטי."},{"app":"fanlife","hook":"Away Days: כל מגרש שהמועדון שיחק בו באירופה","body":"שקף 1: מפה של כל משחקי החוץ\nשקף 2: כל מגרש עם תמונה\nשקף 3: כפתור \"הייתי שם\"\nשקף 4: \"המסע שלי\" נאסף אוטומטית\nשקף 5: איפה היית?","visual":"מפת אירופה בדיו, קווים אדומים בין ערים."},{"app":"offsides","hook":"Momentum: לנחש מה יקרה בדקות הקרובות","body":"שקף 1: המערכת שואלת: יהיה גול ב-10 הדקות הבאות?\nשקף 2: הסיכויים זזים לפי המשחק\nשקף 3: עונים כן/לא\nשקף 4: מדייקים — עולים\nשקף 5: הכל וירטואלי, הכל כיף","visual":"גרף מומנטום חי עם חץ זינוק."},{"app":"theworker","hook":"הסקרים של הפועל: בלי ספירה מזויפת","body":"שקף 1: מי הבלם הכי טוב?\nשקף 2: מי החלוץ?\nשקף 3: מי הקפטן?\nשקף 4: פתק הצבעה מודפס\nשקף 5: שתף את הפתק שלך","visual":"פתק הצבעה מודפס עם 8 שורות וסימני X."},{"app":"fanlife","hook":"ארכיון החולצות: מ-1949 עד היום","body":"שקף 1: חולצה מהארכיון\nשקף 2: חולצה\nשקף 3: חולצה\nשקף 4: איזו הכי יפה?\nשקף 5: תבנה את שלך בסטודיו","visual":"חולצות על רקע בד, צילום מוצר נקי."},{"app":"all","hook":"מה אתה סוג של אוהד?","body":"שקף 1: האנליסט — OFFSIDES\nשקף 2: המנהל — DUBID / Legends Manager\nשקף 3: ההיסטוריון — THE WORKER\nשקף 4: הנוסטלגי — FAN LIFE LIFE\nשקף 5: העצבני — FUCK YOU (רק בדרבי)","visual":"חמש דמויות קומיקס, כל אחת עם אביזר."},{"app":"dubid","hook":"סטטיסטיקה ששווה נקודות","body":"שקף 1: מי מבקיע בכל משחק בית?\nשקף 2: איזה שוער שומר נקי?\nשקף 3: מי מבשל הכי הרבה?\nשקף 4: מי פצוע?\nשקף 5: הכל בכרטיס השחקן בדוביד","visual":"טבלאות סטטיסטיקה מעוצבות בסגנון עיתון."},{"app":"fanlife","hook":"משחק הזיכרון של המועדון","body":"שקף 1: קלפים הפוכים\nשקף 2: כל זוג — רגע מההיסטוריה\nשקף 3: מוצאים זוג, קוראים את הסיפור\nשקף 4: על זמן\nשקף 5: שער 6 ב-FAN LIFE","visual":"רשת קלפ